@testset "joekuofirst" begin
    nDim = 3
    n = 10
    #found via external Fortran implementation
    ref = [
        [0.0, 0.0, 0.0],
        [0.5, 0.5, 0.5],
        [0.75, 0.25, 0.25],
        [0.25, 0.75, 0.75],
        [0.375, 0.375, 0.625],
        [0.875, 0.875, 0.125],
        [0.625, 0.125, 0.875],
        [0.125, 0.625, 0.375],
        [0.1875, 0.3125, 0.9375],
        [0.6875, 0.8125, 0.4375],
    ]
    sobol = ScrambledSobolSeq(nDim, n, NoScrambling())
    points = zeros(nDim)
    for i = 2:n
        next!(sobol, points)
        println(points)
        for j = 1:nDim
            @test isapprox(ref[i][j], points[j], atol = 1e-15)
        end
    end
    skipTo!(sobol, 0)
    for i = 1:n
        next!(sobol, points)
        #println(points)
        for j = 1:nDim
            @test isapprox(ref[i][j], points[j], atol = 1e-15)
        end
    end
end


