@testset "owenmaxd20" begin
    nDim = 2
    rng = OriginalScramblingRng()
    points = zeros(nDim)
    #found via external Fortran implementation
    eiRefs =
        [0.9971220635606457, 0.9993152184276646, 0.998860199836189, 0.9999870322276321] #Owen points are now centered in their 2^-maxd cell (open interval), the external Fortran values were 0.99712205451487534, 0.99931521505777710, 0.99886019692965533, 0.99998703162784253
    n = 1024 * 4 + 1
    sobol = ScrambledSobolSeq(nDim, n, Owen(20, rng))
    sum = 0.0
    twoK = 512
    indexTwoK = 1
    for i = 1:n
        f = 1.0
        next!(sobol, points)
        for j = 1:nDim
            f = f * abs(4 * points[j] - 2)
        end
        if (i % twoK == 0)
            println("i=", i)
            println("ei=", (sum / i))
            @test isapprox(eiRefs[indexTwoK], sum / i, atol = 1e-15)
            indexTwoK += 1
            twoK *= 2
        end
        sum += f
    end
end

