@testset "niederreiter_nut_21201" begin
    # Test creation and generation for lower dimension
    seq_21201 = ScrambledSobolSeq(5, 10, NoScrambling(), niederreiter_nut_21201)
    @test AQFED.Random.ndims(seq_21201) == 5
    pts = zeros(Float64, 5)
    next!(seq_21201, pts)
    @test all(0.0 .<= pts .<= 1.0)

    # Test alias niederreiter_nut_s21201
    seq_alias = ScrambledSobolSeq(5, 10, NoScrambling(), niederreiter_nut_s21201)
    pts_alias = zeros(Float64, 5)
    next!(seq_alias, pts_alias)
    @test pts == pts_alias

    # Test high dimension up to max dimension 21201
    seq_max = ScrambledSobolSeq(21201, 10, NoScrambling(), niederreiter_nut_21201)
    @test AQFED.Random.ndims(seq_max) == 21201
    pts_max = zeros(Float64, 21201)
    next!(seq_max, pts_max)
    @test all(0.0 .<= pts_max .<= 1.0)

    # Test distinctness from joe_kuo and niederreiter_nut (1111 max dim)
    seq_jk = ScrambledSobolSeq(5, 10, NoScrambling(), joe_kuo)
    pts_jk = zeros(Float64, 5)
    next!(seq_jk, pts_jk)
    #the first point is 0.5 in every dimension for any direction numbers, and both sources share the low dimensions: compare the next points
    isDifferent = false
    for _ = 1:7
        next!(seq_21201, pts)
        next!(seq_jk, pts_jk)
        isDifferent |= pts != pts_jk
    end
    @test isDifferent
